"""Shared conditional analysis over canonical Python syntax, without source heuristics."""
from .common import *
SEMANTIC='l2070_batching.conditional_step.ConditionalStep'
PHYSICAL='impl.common.l2070_server_plan.steps.sql_conditional.SqlConditionalStep'
COMPILER='impl.common.l2070_server_plan.steps._conditional_compile.compile_sql_conditional_step'
EXECUTOR='impl.common.l2070_server_plan.sql_backend_executor.SqlBackendExecutor'
VALIDATION='require_sql_physical_conditional'
MESSAGES={
 'semantic-compile':'semantic ConditionalStep must reject direct compilation with TypeError',
 'semantic-level':'semantic ConditionalStep lowering level must require physical lowering',
 'executor-hook':'SqlBackendExecutor must define _lower_conditional_step',
 'physical-level':'SqlConditionalStep must be terminal at lowering level zero',
 'physical-role':'SqlConditionalStep must have the SQL execution role',
 'physical-compile':'SqlConditionalStep.compile must delegate to the approved physical compiler',
 'semantic-contract':'semantic typed conditional contract must unconditionally reject with TypeError',
 'physical-contract':'physical typed conditional contract must override semantic rejection without backend selection',
 'compiler-contract':'compiler typed conditional contract must validate its SqlConditionalStep before strategy selection',
 'lowering-contract':'lowering typed conditional contract must produce SqlConditionalStep from the semantic conditional',
}
MAIN={'semantic-compile','executor-hook','semantic-contract','physical-contract','compiler-contract','lowering-contract'}

def dotted(unwrap):
 step="parent.kind='Attribute' AND child.field='value'"+(" OR parent.kind='Call' AND child.field='func'" if unwrap else '')
 terminal="n.kind NOT IN ('Name','Attribute'"+(",'Call'" if unwrap else '')+")"
 return "WITH RECURSIVE walk(__path,root,id,suffix) AS (SELECT __path,id,id,'' FROM a WHERE kind IN ('Name','Attribute','Call') UNION ALL SELECT w.__path,w.root,child.id,CASE WHEN parent.kind='Attribute' THEN '.'||parent.name||w.suffix ELSE w.suffix END FROM walk w JOIN a parent ON parent.__path=w.__path AND parent.id=w.id JOIN a child ON child.__path=parent.__path AND child.parent=parent.id WHERE "+step+") SELECT w.__path,w.root id,CASE WHEN n.kind='Name' THEN n.name||w.suffix ELSE nullif(substr(w.suffix,2),'') END name FROM walk w JOIN a n ON n.__path=w.__path AND n.id=w.id WHERE n.kind='Name' OR ("+terminal+")"

def clauses():
 stages=[S('local_names',dotted(True),('__path','id')),S('context_names',dotted(False),('__path','id')),
 S('shared_aliases',"SELECT alias.__path,alias.id,CASE WHEN alias.alias!='' THEN alias.alias WHEN owner.kind='Import' THEN rx_extract(alias.name,'^([^.]+)',1) ELSE alias.name END local,CASE WHEN owner.kind='ImportFrom' THEN owner.module||'.'||alias.name ELSE alias.name END origin FROM a alias JOIN a owner ON owner.__path=alias.__path AND owner.id=alias.parent WHERE alias.kind='alias' AND (owner.kind='Import' OR owner.kind='ImportFrom' AND owner.module!='')",('__path','local','id')),
 S('class_events',"SELECT c.*,replace(coalesce(rx_extract(c.__path,'(?:^|/)((?:impl|l2070_batching|scripts)/.*)\\.py$',1),rx_extract(c.__path,'(?:^|/)([^/]+)\\.py$',1)),'/','.')||'.'||c.name qualified_name FROM classes c",('__path','id'),('__path','name')),
 S('shared_classes',"SELECT n.* FROM class_events n WHERE n.id=(SELECT max(last.id) FROM class_events last WHERE last.__path=n.__path AND last.name=n.name)",('__path','id'),('qualified_name',)),
 S('method_events',"SELECT f.*,owner.name class_name,(SELECT max(c.id) FROM class_events c WHERE c.__path=f.__path AND c.name=owner.name AND c.id<f.id) class_event FROM functions f JOIN classes owner ON owner.__path=f.__path AND owner.id=f.cls",('__path','class_event','name','id')),
 S('shared_methods',"SELECT m.*,c.qualified_name FROM method_events m JOIN shared_classes c ON c.__path=m.__path AND c.id=m.class_event WHERE m.id=(SELECT max(last.id) FROM method_events last WHERE last.__path=m.__path AND last.class_event=m.class_event AND last.name=m.name)",('__path','id'),('__path','class_event','name')),
 S('shared_functions',"SELECT f.*,replace(coalesce(rx_extract(f.__path,'(?:^|/)((?:impl|l2070_batching|scripts)/.*)\\.py$',1),rx_extract(f.__path,'(?:^|/)([^/]+)\\.py$',1)),'/','.')||'.'||f.name qualified_name FROM functions f WHERE f.cls IS NULL AND f.id=(SELECT max(last.id) FROM functions last WHERE last.__path=f.__path AND last.cls IS NULL AND last.name=f.name)",('__path','id'),('qualified_name',)),
 S('resolved_bases',"SELECT c.__path,c.id,coalesce((SELECT alias.origin FROM shared_aliases alias WHERE alias.__path=c.__path AND alias.local=rx_extract(q.name,'^([^.]+)',1) AND alias.id<c.id ORDER BY alias.id DESC LIMIT 1),rx_extract(q.name,'^([^.]+)',1))||coalesce(rx_extract(q.name,'^[^.]+([.].*)$',1),'') base FROM shared_classes c JOIN a b ON b.__path=c.__path AND b.parent=c.id AND b.field='bases' JOIN local_names q ON q.__path=b.__path AND q.id=b.id",('__path','id')),
 S('derived_conditionals',"WITH RECURSIVE derived(name) AS (SELECT "+q(SEMANTIC)+" UNION SELECT c.qualified_name FROM derived d JOIN resolved_bases b ON b.base=d.name JOIN shared_classes c ON c.__path=b.__path AND c.id=b.id) SELECT * FROM derived",('name',)),
 S('method_nodes',"SELECT n.*,m.id method,m.class_event,m.name method_name,m.class_name FROM a n JOIN functions owner ON owner.__path=n.__path AND owner.id=n.fn JOIN classes lexical ON lexical.__path=n.__path AND lexical.id=n.cls JOIN method_events m ON m.__path=n.__path AND m.class_name=lexical.name JOIN shared_classes final_class ON final_class.__path=m.__path AND final_class.id=m.class_event AND m.name=owner.name WHERE m.id<=n.id AND m.class_event=(SELECT max(c.id) FROM class_events c WHERE c.__path=n.__path AND c.name=lexical.name AND c.id<=n.id) AND m.id=(SELECT max(prior.id) FROM method_events prior WHERE prior.__path=n.__path AND prior.class_event=m.class_event AND prior.name=m.name AND prior.id<=n.id)",('__path','id'),('__path','method')),
 S('type_error_raises',"SELECT r.__path,r.id FROM a r JOIN a exc ON exc.__path=r.__path AND exc.parent=r.id AND exc.field='exc' JOIN local_names q ON q.__path=exc.__path AND q.id=exc.id WHERE r.kind='Raise' AND q.name='TypeError'",('__path','id')),
 S('contract_blocks',"SELECT block.*,row_number() OVER(PARTITION BY block.__path ORDER BY block.last-block.id,block.id DESC,block.role) sequence FROM (SELECT owner.__path,owner.id,owner.last,child.field role FROM a owner JOIN a child ON child.__path=owner.__path AND child.parent=owner.id WHERE owner.kind IN ('FunctionDef','AsyncFunctionDef','If','match_case') AND child.field IN ('body','orelse') GROUP BY owner.__path,owner.id,child.field) block",('__path','sequence'),('__path','id','role')),
 ]
 # This map contains one Boolean per block. It stores no AST rows or properties.
 key="CAST(b.id AS TEXT)||':'||b.role"
 result=lambda parent,role:"coalesce(json_extract(fold.state,'$.\"'||"+parent+"||':"+role+"\"'),0)=1"
 qualifies="stmt.kind='Raise' AND EXISTS(SELECT 1 FROM type_error_raises r WHERE r.__path=stmt.__path AND r.id=stmt.id) OR stmt.kind='If' AND "+result('stmt.id','body')+' AND '+result('stmt.id','orelse')+" OR stmt.kind='Match' AND EXISTS(SELECT 1 FROM a arm WHERE arm.__path=stmt.__path AND arm.parent=stmt.id AND arm.field='cases') AND NOT EXISTS(SELECT 1 FROM a arm WHERE arm.__path=stmt.__path AND arm.parent=stmt.id AND arm.field='cases' AND NOT ("+result('arm.id','body')+'))'
 value="EXISTS(SELECT 1 FROM a stmt WHERE stmt.__path=b.__path AND stmt.parent=b.id AND stmt.field=b.role AND stmt.position<=coalesce((SELECT min(barrier.position) FROM a barrier WHERE barrier.__path=b.__path AND barrier.parent=b.id AND barrier.field=b.role AND barrier.kind IN ('Raise','Return','Yield','YieldFrom')),2147483647) AND ("+qualifies+'))'
 stages += [S('block_results',"WITH RECURSIVE fold(__path,sequence,state) AS (SELECT DISTINCT __path,0,'{}' FROM contract_blocks UNION ALL SELECT b.__path,b.sequence,substr(fold.state,1,length(fold.state)-1)||CASE WHEN length(fold.state)>2 THEN ',' ELSE '' END||json_quote("+key+")||':'||CAST(("+value+") AS TEXT)||'}' FROM fold JOIN contract_blocks b ON b.__path=fold.__path AND b.sequence=fold.sequence+1) SELECT __path,state FROM fold WHERE sequence=(SELECT max(b.sequence) FROM contract_blocks b WHERE b.__path=fold.__path)",('__path',)),
 S('method_colors',"SELECT m.__path,m.id,coalesce(json_extract(b.state,'$.\"'||m.id||':body\"'),0) always_raises,EXISTS(SELECT 1 FROM method_nodes n JOIN type_error_raises r ON r.__path=n.__path AND r.id=n.id WHERE n.__path=m.__path AND n.method=m.id) raises_type_error,EXISTS(SELECT 1 FROM a n WHERE n.__path=m.__path AND n.id BETWEEN m.id AND m.last AND n.kind='Name' AND n.name='BackendType') OR EXISTS(SELECT 1 FROM a n WHERE n.__path=m.__path AND n.id BETWEEN m.id AND m.last AND n.kind='Attribute' AND n.name IN ('backend_type','is_sql_backend','dialect')) AND EXISTS(SELECT 1 FROM a n WHERE n.__path=m.__path AND n.id BETWEEN m.id AND m.last AND n.kind IN ('If','IfExp','Match')) backend_selection FROM shared_methods m LEFT JOIN block_results b ON b.__path=m.__path",('__path','id')),
 S('method_returns',"SELECT n.*,value.kind expression_kind,value.value value_text,q.name dotted FROM method_nodes n JOIN a value ON value.__path=n.__path AND value.parent=n.id AND value.field='value' LEFT JOIN local_names q ON q.__path=value.__path AND q.id=value.id WHERE n.kind='Return'",('__path','method')),
 S('shared_calls',"SELECT n.__path,n.method,n.id,n.line,q.name FROM method_nodes n JOIN calls call ON call.__path=n.__path AND call.id=n.id LEFT JOIN context_names q ON q.__path=call.__path AND q.id=call.callee_id WHERE n.kind='Call'",('__path','method','name')),
 S('callable_parameters',"SELECT DISTINCT m.__path,m.id method,p.name FROM shared_methods m JOIN parameters p ON p.__path=m.__path AND p.fn=m.id JOIN a name ON name.__path=p.__path AND name.id BETWEEN p.id AND p.last AND name.kind='Name' AND name.name='Callable'",('__path','method','name')),
 S('branch_names',"WITH RECURSIVE targets(__path,method,event,id) AS (SELECT loop.__path,loop.method,loop.id,target.id FROM method_nodes loop JOIN a iter ON iter.__path=loop.__path AND iter.parent=loop.id AND iter.field='iter' JOIN local_names q ON q.__path=iter.__path AND q.id=iter.id JOIN a target ON target.__path=loop.__path AND target.parent=loop.id AND target.field='target' WHERE loop.kind='For' AND rx_matches(q.name,'then_plan\\.steps|else_plan\\.steps|conditional_branch_steps|then_steps|else_steps') UNION ALL SELECT t.__path,t.method,t.event,child.id FROM targets t JOIN a parent ON parent.__path=t.__path AND parent.id=t.id AND parent.kind IN ('Tuple','List') JOIN a child ON child.__path=parent.__path AND child.parent=parent.id AND child.field='elts') SELECT t.__path,t.method,t.event,n.name FROM targets t JOIN a n ON n.__path=t.__path AND n.id=t.id AND n.kind='Name'",('__path','method','name','event'))]
 stages.append(S('method_backend_controls',"SELECT n.* FROM method_nodes n JOIN a test ON test.__path=n.__path AND test.parent=n.id AND test.field IN ('test','subject') JOIN a attr ON attr.__path=test.__path AND attr.id BETWEEN test.id AND test.last AND attr.kind='Attribute' AND attr.name IN ('backend_type','is_sql_backend') WHERE n.kind IN ('If','IfExp','Match') AND NOT EXISTS(SELECT 1 FROM a nested JOIN a predicate ON predicate.__path=nested.__path AND predicate.parent=nested.id AND predicate.field IN ('test','subject') WHERE nested.__path=test.__path AND nested.id BETWEEN test.id AND test.last AND nested.kind IN ('If','IfExp','Match') AND attr.id BETWEEN predicate.id AND predicate.last) GROUP BY n.__path,n.id",('__path','class_name','method_name','line')))
 rows=[]
 def add(detector,table,where,message=None,node='n',order=None,extra=''):
  rows.append(row('CONDA-005',q(MESSAGES[detector]) if message is None else message,table,where,node=node,order=order,extra=','+q(detector)+' detector'+extra))
 method=lambda name,condition='1':"EXISTS(SELECT 1 FROM shared_methods m WHERE m.__path=n.__path AND m.class_event=n.id AND m.name="+q(name)+' AND ('+condition+'))'
 calls=lambda name,condition:method(name,"EXISTS(SELECT 1 FROM shared_calls call WHERE call.__path=m.__path AND call.method=m.id AND ("+condition+'))')
 add('semantic-compile','shared_classes n','n.qualified_name='+q(SEMANTIC)+' AND NOT '+method('compile','EXISTS(SELECT 1 FROM method_colors color WHERE color.__path=m.__path AND color.id=m.id AND color.raises_type_error)'))
 integer="r.expression_kind='Constant' AND EXISTS(SELECT 1 FROM a v WHERE v.__path=r.__path AND v.parent=r.id AND v.field='value' AND v.value_kind IN ('int','bool'))"
 add('semantic-level','shared_classes n','n.qualified_name='+q(SEMANTIC)+" AND (NOT "+method('level',"EXISTS(SELECT 1 FROM method_returns r WHERE r.__path=m.__path AND r.method=m.id AND "+integer+")")+' OR '+method('level',"EXISTS(SELECT 1 FROM method_returns r WHERE r.__path=m.__path AND r.method=m.id AND "+integer+" AND CASE r.value_text WHEN 'True' THEN 1 WHEN 'False' THEN 0 ELSE CAST(r.value_text AS INTEGER) END<=0)" )+')')
 add('executor-hook','shared_classes n','n.qualified_name='+q(EXECUTOR)+' AND NOT '+method('_lower_conditional_step'))
 physicallevel=method('level',"(SELECT count(*) FROM method_returns r WHERE r.__path=m.__path AND r.method=m.id AND "+integer+")=1 AND EXISTS(SELECT 1 FROM method_returns r WHERE r.__path=m.__path AND r.method=m.id AND "+integer+" AND (r.value_text='False' OR r.value_text='0'))")
 add('physical-level','shared_classes n','n.qualified_name='+q(PHYSICAL)+' AND NOT ('+physicallevel+')')
 add('physical-role','shared_classes n','n.qualified_name='+q(PHYSICAL)+' AND NOT '+method('execution_role',"EXISTS(SELECT 1 FROM method_returns r WHERE r.__path=m.__path AND r.method=m.id AND r.dotted='StepExecutionRole.SQL')"))
 add('physical-compile','shared_classes n','n.qualified_name='+q(PHYSICAL)+' AND NOT '+calls('compile',"substr(call.name,-28)='compile_sql_conditional_step'"))
 present="EXISTS(SELECT 1 FROM shared_classes WHERE qualified_name IN "+literals([SEMANTIC,PHYSICAL,EXECUTOR])+") OR EXISTS(SELECT 1 FROM shared_functions WHERE qualified_name="+q(COMPILER)+')'
 contracts=[('semantic-contract',SEMANTIC,'NOT '+method(VALIDATION,'EXISTS(SELECT 1 FROM method_colors color WHERE color.__path=m.__path AND color.id=m.id AND color.always_raises)')),('physical-contract',PHYSICAL,"n.qualified_name NOT IN (SELECT name FROM derived_conditionals) OR NOT "+method(VALIDATION,'EXISTS(SELECT 1 FROM method_colors color WHERE color.__path=m.__path AND color.id=m.id AND NOT color.always_raises AND NOT color.backend_selection)')),('lowering-contract',EXECUTOR,'NOT '+calls('_lower_conditional_step',"substr(call.name,-32)='SqlConditionalStep.from_semantic'"))]
 for detector,owner,invalid in contracts:
  add(detector,'shared_classes n','n.qualified_name='+q(owner)+' AND ('+invalid+') AND ('+present+')')
  path=owner.rsplit('.',1)[0].replace('.','/')+'.py'
  rows.append("SELECT "+q(path)+" path,0 start_byte,0 end_byte,1 line,'CONDA-005' issue,"+q(MESSAGES[detector])+" message,'missing' identity,0 phase,0 ordering,'' symbol,'' sort_name,"+q(detector)+" detector WHERE ("+present+") AND NOT EXISTS(SELECT 1 FROM shared_classes WHERE qualified_name="+q(owner)+')')
 # Function contracts use aliases in force when the function declaration is visited.
 param="EXISTS(SELECT 1 FROM parameters p JOIN a ann ON ann.__path=p.__path AND ann.parent=p.id AND ann.field='annotation' JOIN local_names q ON q.__path=ann.__path AND q.id=ann.id WHERE p.__path=n.__path AND p.fn=n.id AND p.name='step' AND p.field IN ('posonlyargs','args','kwonlyargs') AND coalesce((SELECT alias.origin FROM shared_aliases alias WHERE alias.__path=n.__path AND alias.local=rx_extract(q.name,'^([^.]+)',1) AND alias.id<n.id ORDER BY alias.id DESC LIMIT 1),rx_extract(q.name,'^([^.]+)',1))||coalesce(rx_extract(q.name,'^[^.]+([.].*)$',1),'')="+q(PHYSICAL)+')'
 backend=desc('n',alias='attr',condition="attr.kind='Name' AND attr.name='BackendType'")+" OR ("+desc('n',alias='attr',condition="attr.kind='Attribute' AND attr.name IN ('backend_type','is_sql_backend','dialect')")+' AND '+desc('n',alias='control',condition="control.kind IN ('If','IfExp','Match')")+')'
 valid=param+' AND NOT ('+backend+") AND EXISTS(SELECT 1 FROM calls call JOIN local_names q ON q.__path=call.__path AND q.id=call.callee_id WHERE call.__path=n.__path AND call.id BETWEEN n.id AND n.last AND q.name='step."+VALIDATION+"' AND NOT EXISTS(SELECT 1 FROM calls strategy JOIN local_names sq ON sq.__path=strategy.__path AND sq.id=strategy.callee_id WHERE strategy.__path=n.__path AND strategy.id BETWEEN n.id AND n.last AND substr(sq.name,-21)='_conditional_strategy' AND strategy.line<=call.line))"
 add('compiler-contract','shared_functions n','n.qualified_name='+q(COMPILER)+' AND NOT ('+valid+') AND ('+present+')')
 path=COMPILER.rsplit('.',1)[0].replace('.','/')+'.py';rows.append("SELECT "+q(path)+" path,0 start_byte,0 end_byte,1 line,'CONDA-005' issue,"+q(MESSAGES['compiler-contract'])+" message,'missing' identity,0 phase,0 ordering,'' symbol,'' sort_name,'compiler-contract' detector WHERE ("+present+") AND NOT EXISTS(SELECT 1 FROM shared_functions WHERE qualified_name="+q(COMPILER)+')')
 derived="EXISTS(SELECT 1 FROM shared_classes cls JOIN derived_conditionals d ON d.name=cls.qualified_name WHERE cls.__path=n.__path AND cls.id=n.class_event)"
 # Parent links for an assignment's value are not yet recorded at on_Assign.
 # The original assignment callback is inert; Store events provide these findings.
 source="method_nodes n JOIN a receiver ON receiver.__path=n.__path AND receiver.parent=n.id AND receiver.field='value' AND receiver.kind='Name' AND receiver.name='self' LEFT JOIN a owner ON owner.__path=n.__path AND owner.id=n.parent AND owner.kind IN ('Assign','AnnAssign') LEFT JOIN a expression ON expression.__path=owner.__path AND expression.parent=owner.id AND expression.field='value'"
 add('runtime-state',source,derived+" AND n.method_name!='__init__' AND n.kind='Attribute' AND n.context='Store'","'conditional method '||n.class_name||'.'||n.method_name||' stores runtime instance state in '||n.name_repr")
 callback="expression.kind='Lambda' OR expression.kind='Name' AND EXISTS(SELECT 1 FROM callable_parameters p WHERE p.__path=n.__path AND p.method=n.method AND p.name=expression.name)"
 add('runtime-callback',source,derived+" AND n.method_name='__init__' AND n.kind='Attribute' AND n.context='Store' AND ("+callback+")","'conditional class '||char(39)||n.class_name||char(39)||' owns runtime callback field '||n.name_repr")
 source="a n JOIN shared_classes cls ON cls.__path=n.__path AND cls.id=n.cls JOIN a target ON target.__path=n.__path AND target.parent=n.id AND target.field='target' JOIN a atom ON atom.__path=n.__path AND atom.id BETWEEN n.id AND n.last AND atom.kind='Name' AND atom.name='Callable'"
 add('declared-callback',source,"n.kind='AnnAssign' AND n.fn IS NULL AND cls.qualified_name IN (SELECT name FROM derived_conditionals) AND (target.kind='Name' OR target.kind='Attribute' AND "+child('target','value',alias='recv',condition="recv.kind='Name' AND recv.name='self'")+')',"'conditional class '||char(39)||cls.name||char(39)||' owns runtime callback field '||target.name_repr",order='n.id*1000+atom.id*0.001')
 source="method_nodes n JOIN calls call ON call.__path=n.__path AND call.id=n.id JOIN a receiver ON receiver.__path=call.__path AND receiver.id=call.receiver AND receiver.kind='Name'"
 add('child-compilation',source,derived+" AND call.callee_kind='Attribute' AND call.callee='compile' AND EXISTS(SELECT 1 FROM branch_names b WHERE b.__path=n.__path AND b.method=n.method AND b.name=receiver.name AND b.event<n.id)","'conditional method '||n.class_name||'.'||n.method_name||' performs child compilation'")
 source="method_backend_controls n"
 add('backend-control',source,derived+" AND n.id=(SELECT min(first.id) FROM method_backend_controls first WHERE first.__path=n.__path AND first.class_name=n.class_name AND first.method_name=n.method_name AND first.line=n.line)","'conditional method '||n.class_name||'.'||n.method_name||' selects through backend identity'")
 # Distinct report stages share the same canonical producer and finite relation graph.
 for index in range(0,len(rows),4):stages.append(S('conditional_findings_'+str(index//4),' UNION ALL '.join(rows[index:index+4])))
 report=' UNION ALL '.join('SELECT * FROM conditional_findings_'+str(i//4) for i in range(0,len(rows),4))
 query="SELECT * FROM ("+report+") WHERE detector IN "+literals(MAIN)
 item=make_clause('conditional-structural-contracts',stages,select_entry(query,{'conditional_architecture_findings':report}),partition=False,locations=[n.rsplit('.',1)[0].replace('.','/')+'.py' for n in [SEMANTIC,PHYSICAL,COMPILER,EXECUTOR]])
 item['relational']['line']='line';item['relational']['key']=['detector','identity']
 return [item]
